            user1Cert.setUserId(user1User.getId());
            user1Cert.setRealName("李用户");
            user1Cert.setIdCardNumber("310101199001015678");
            user1Cert.setCertifiedAt(LocalDateTime.of(2024, 1, 15, 14, 0, 0));
            certMapper.insert(user1Cert);
        }
    }
